package io.github.bytejuno.thetacore.plugin

import io.github.bytejuno.thetacore.sample.blockedprovider.FixtureDocument
import io.github.bytejuno.thetacore.sample.blockedprovider.ReadMode
import org.junit.Assert.*
import org.junit.Test

/** The provider's real generated bytes must pass the host parser, not just java.util.zip. */
class BlockedProviderFixtureParserTest {
    @Test fun controlArchivePassesHostParser() = assertAccepted(
        FixtureDocument.CONTROL, ReadMode.IMMEDIATE, "control", "SOURCE_CONTROL_V1",
    )

    @Test fun delayedArchivePassesHostParser() = assertAccepted(
        FixtureDocument.DELAYED, ReadMode.DELAY, "delayed", "SOURCE_DELAYED_V1",
    )

    @Test fun blockedArchivePassesHostParser() = assertAccepted(
        FixtureDocument.BLOCKED, ReadMode.BLOCK, "blocked", "SOURCE_BLOCKED_V1",
    )

    @Test fun prefixArchivePassesRealHostParser() {
        val contents = linkedMapOf<String, ByteArray>()
        val archive = io.github.bytejuno.thetacore.sample.blockedprovider.PrefixArchive
        val validated = validatePluginDataZip(archive.bytes, hostApiLevel = 1, limits = PluginDataLimits()) { path, bytes ->
            assertNull(contents.put(path, bytes))
        }
        assertEquals(archive.PLUGIN_ID, validated.manifest.id)
        assertTrue(validated.destinations.isEmpty())
        assertEquals(setOf("theta-plugin.json", "skills/source-marker/SKILL.md", "skills/source-padding/SKILL.md"), contents.keys)
        assertEquals(archive.PADDING_BYTES, contents.getValue("skills/source-padding/SKILL.md").size)
        assertTrue(contents.getValue("skills/source-marker/SKILL.md").toString(Charsets.UTF_8).contains("SOURCE_PREFIX_COPY_V1"))
    }

    private fun assertAccepted(document: FixtureDocument, mode: ReadMode, key: String, marker: String) {
        assertEquals(mode, document.mode)
        val contents = linkedMapOf<String, ByteArray>()
        val validated = validatePluginDataZip(document.bytes, hostApiLevel = 1, limits = PluginDataLimits()) { path, bytes ->
            assertNull("Duplicate content callback for $path", contents.put(path, bytes))
        }

        assertEquals(
            PluginDataManifest(
                id = "io.github.bytejuno.thetacore.fixture.source.$key",
                name = "Source fixture $key",
                version = "1",
                versionCode = 1L,
                apiLevel = 1,
                provides = listOf("skills"),
                declares = emptyList(),
            ),
            validated.manifest,
        )
        assertTrue("Inert fixture must not declare network destinations", validated.destinations.isEmpty())
        assertEquals(setOf("theta-plugin.json", "skills/source-marker/SKILL.md"), contents.keys)
        assertEquals(
            "# Source fixture $key\n\nInert local import marker: $marker\n",
            contents.getValue("skills/source-marker/SKILL.md").toString(Charsets.UTF_8),
        )
    }
}
